-- veicoli: prezzo pagato = listino in lari del modello (gli altri modelli: rapporto)
UPDATE vehicles SET price_paid = CASE model WHEN 462 THEN 220000 WHEN 436 THEN 750000 WHEN 410 THEN 690000 WHEN 491 THEN 890000 WHEN 466 THEN 950000 WHEN 547 THEN 1450000 WHEN 529 THEN 1590000 WHEN 543 THEN 1350000 WHEN 461 THEN 1750000 WHEN 422 THEN 1950000 WHEN 549 THEN 1650000 WHEN 500 THEN 2900000 WHEN 405 THEN 3100000 ELSE LEAST(ROUND(price_paid * @tetri_per_dollaro), 1000000000) END WHERE @gia = 0;
INSERT INTO economy_meta (k, v) VALUES ('balances', 'convertiti') ON DUPLICATE KEY UPDATE v = IF(@gia = 0, 'convertiti', v);
INSERT INTO economy_meta (k, v) VALUES ('balances_ratio', CAST(@tetri_per_dollaro AS CHAR)) ON DUPLICATE KEY UPDATE v = IF(@gia = 0, VALUES(v), v);
COMMIT;
-- verifica: nessun saldo negativo o oltre il tetto
SELECT COUNT(*) AS personaggi, SUM(money < 0 OR bank < 0) AS negativi, SUM(money > 1000000000 OR bank > 1000000000) AS oltre_tetto, ROUND(SUM(money + bank) / 100, 2) AS totale_lari FROM characters;
